import com.fxrates.feature.rates.details.model.HistoryItem
import com.fxrates.feature.rates.model.color
import com.fxrates.feature.rates.ui.Centered
import com.fxrates.feature.rates.ui.ErrorState
import com.fxrates.ui.Strings
import com.fxrates.ui.theme.AppTheme

@Composable
fun RateDetailsUiContent(
    component: RateDetailsUiComponent,
    modifier: Modifier = Modifier,
) {
    val state by component.state.collectAsState()
    RateDetailsUiContent(
        state = state,
        onRetry = component::onRetry,
        onBackClick = component::onBackClick,
        modifier = modifier,
    )
}

@Composable
private fun RateDetailsUiContent(
    state: RateDetailsUiState,
    onRetry: () -> Unit,
    onBackClick: () -> Unit,
    modifier: Modifier = Modifier,
) = Column(
    modifier = modifier
        .fillMaxSize()
        .safeDrawingPadding(),
) {
    Header(title = state.title, onBackClick = onBackClick)
    when (val content = state.content) {
        is Content.Loading -> {
            Centered { CircularProgressIndicator() }
        }
        is Content.Error -> {
            ErrorState(onRetry = onRetry)
        }
        is Content.NoData -> {
            Centered { Text(Strings.NO_DATA, style = MaterialTheme.typography.bodyLarge) }
        }
        is Content.Data -> {
            DataList(content = content)
        }
    }
}

@Composable
private fun Header(
    title: String,
    onBackClick: () -> Unit,
) = Row(
    modifier = Modifier
        .fillMaxWidth()
        .padding(horizontal = AppTheme.spacing.m, vertical = AppTheme.spacing.s),
    verticalAlignment = Alignment.CenterVertically,
) {
    TextButton(onClick = onBackClick) {
        Text(Strings.BACK)
    }
    Text(
        text = title,
        style = MaterialTheme.typography.headlineMedium,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        modifier = Modifier.weight(1f),
    )
}

@Composable
private fun DataList(content: Content.Data) = LazyColumn(modifier = Modifier.fillMaxSize()) {
    item {
        CurrentRate(rate = content.rate, date = content.date)
    }
    item {
        ChangeBlock(change = content.change)
    }
    item {
        Text(
            text = Strings.RATE_HISTORY_TITLE,
            style = MaterialTheme.typography.titleMedium,
            modifier = Modifier.padding(horizontal = AppTheme.spacing.m, vertical = AppTheme.spacing.s),
        )
        HorizontalDivider()
    }
    items(items = content.history, key = HistoryItem::date) { item ->
        HistoryRow(item = item)
        HorizontalDivider()
    }
}

@Composable
private fun CurrentRate(
    rate: String,
    date: String,
) = Column(
    modifier = Modifier
        .fillMaxWidth()
        .padding(horizontal = AppTheme.spacing.m, vertical = AppTheme.spacing.s),
) {
    Text(rate, style = MaterialTheme.typography.headlineSmall)
    Text(date, style = MaterialTheme.typography.bodyMedium, color = AppTheme.colors.neutral)
}

@Composable
private fun ChangeBlock(change: Change) = Column(
    modifier = Modifier
        .fillMaxWidth()
        .padding(horizontal = AppTheme.spacing.m, vertical = AppTheme.spacing.s),
) {
    when (change) {
        is Change.NotEnoughData -> {
            Text(Strings.NOT_ENOUGH_DATA, style = MaterialTheme.typography.bodyMedium)
        }
        is Change.Value -> {
            Text(change.period, style = MaterialTheme.typography.bodyMedium, color = AppTheme.colors.neutral)
            Text(change.absolute, style = MaterialTheme.typography.titleMedium, color = change.trend.color())
            Text(change.percent, style = MaterialTheme.typography.titleMedium, color = change.trend.color())
        }
    }
}

@Composable
private fun HistoryRow(item: HistoryItem) = Row(
    modifier = Modifier
        .fillMaxWidth()
        .padding(horizontal = AppTheme.spacing.m, vertical = AppTheme.spacing.s),
    verticalAlignment = Alignment.CenterVertically,
) {
    Text(item.date, style = MaterialTheme.typography.bodyLarge, modifier = Modifier.weight(1f))
    Text(item.rate, style = MaterialTheme.typography.titleMedium)
}

@Preview
@Composable
private fun RateDetailsUiContentPreview(
    @PreviewParameter(RateDetailsUiStatePreviewProvider::class) state: RateDetailsUiState,
) = AppTheme {
    RateDetailsUiContent(
        state = state,
        onRetry = {},
        onBackClick = {},
    )
}
package com.fxrates.feature.rates.details

import androidx.compose.runtime.Immutable
import com.fxrates.core.utils.Empty
import com.fxrates.feature.rates.details.model.HistoryItem
import com.fxrates.feature.rates.model.Trend

@Immutable
internal data class RateDetailsUiState(
    val title: String = String.Empty,
    val content: Content = Content.Loading,
) {

    @Immutable
    sealed class Content {

        data object Loading : Content()

        data object Error : Content()

        data object NoData : Content()

        /**
         * @property rate the latest rate, e.g. `1 USD = 0.8900 EUR`.
         * @property date the date of the latest rate.
         * @property change the change from the earliest to the latest point, or not enough data.
         * @property history the rate of every day of the period, newest first.
         */
        data class Data(
            val rate: String,
            val date: String,
            val change: Change,
            val history: List<HistoryItem>,
        ) : Content()

    }

    @Immutable
    sealed class Change {

        /** Fewer than two points or an earliest rate of zero: the change is undefined. */
        data object NotEnoughData : Change()

        data class Value(
            val period: String,
            val absolute: String,
            val percent: String,
            val trend: Trend,
        ) : Change()

    }

}
package com.fxrates.feature.rates.details

import com.fxrates.core.format.NumberFormatter
import com.fxrates.core.money.RateChangeCalculator
import com.fxrates.core.utils.Resource
import com.fxrates.domain.model.RatePoint
import com.fxrates.feature.rates.details.RateDetailsUiState.Change
import com.fxrates.feature.rates.details.RateDetailsUiState.Content
import com.fxrates.feature.rates.details.model.HistoryItem
import com.fxrates.feature.rates.details.mvi.RateDetailsStore
import com.fxrates.feature.rates.model.toTrend
import com.fxrates.ui.Strings
import me.tatarka.inject.annotations.Inject

@Inject
internal class RateDetailsUiStateConverter {

    fun createUiState(state: RateDetailsStore.State): RateDetailsUiState {
        return RateDetailsUiState(
            title = Strings.rateDetailsTitle(base = state.base, code = state.code),
            content = createContent(state),
        )
    }

    private fun createContent(state: RateDetailsStore.State): Content = when (val history = state.history) {
        is Resource.Loading -> {
            Content.Loading
        }
        is Resource.Error -> {
            Content.Error
        }
        is Resource.Data -> {
            createData(state = state, points = history.value)
        }
    }

    private fun createData(state: RateDetailsStore.State, points: List<RatePoint>): Content {
        if (points.isEmpty()) return Content.NoData
        val last = points.last()
        return Content.Data(
            rate = Strings.currentRate(
                base = state.base,
                rate = NumberFormatter.formatRate(last.rate),
                code = state.code,
            ),
            date = last.date.toString(),
            change = createChange(points = points),
            history = points.asReversed().map(::toItem),
        )
    }

    private fun createChange(points: List<RatePoint>): Change {
        if (points.size < 2) return Change.NotEnoughData
        val first = points.first()
        val last = points.last()
        val change = RateChangeCalculator.calculate(first.rate, last.rate) ?: return Change.NotEnoughData
        return Change.Value(
            period = Strings.changePeriod(start = first.date.toString(), end = last.date.toString()),
            absolute = NumberFormatter.formatSignedRate(change.absolute),
            percent = NumberFormatter.formatSignedPercent(change.percent),
            trend = change.toTrend(),
        )
    }

    private fun toItem(point: RatePoint): HistoryItem {
        return HistoryItem(date = point.date.toString(), rate = NumberFormatter.formatRate(point.rate))
    }

}
